-- Mihver Kafe Veritabanı Oluşturma Scripti
-- Oluşturan: Salih Hocaoğlu | EXCEL 751
-- Türk gençlerinin gelişimine katkı sağlamak amacı ile hazırlanmıştır.

IF EXISTS (SELECT * FROM sys.databases WHERE name = 'Mihver')
BEGIN
    ALTER DATABASE Mihver SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE Mihver;
END
GO

CREATE DATABASE Mihver;
GO

USE Mihver;
GO

CREATE TABLE Masalar (
    MasaID INT IDENTITY(1,1) PRIMARY KEY,
    MasaNo INT NOT NULL,
    Konum NVARCHAR(50), -- Örn: 'Bahçe Önü', 'İç Mekan'
	Kapasite INT NOT NULL, -- Masa kapasitesi
	
);


CREATE TABLE Urunler (
    UrunID INT IDENTITY(1,1) PRIMARY KEY,
    UrunAdi NVARCHAR(100),
    Kategori NVARCHAR(50), -- 'Dunya Mutfagi', 'Tatli', 'Icecek'
    Fiyat DECIMAL(10,2),
    Aciklama NVARCHAR(200) -- Ürün açıklaması

);

CREATE TABLE Musteriler (
    MusteriID INT IDENTITY(1,1) PRIMARY KEY,
    Ad NVARCHAR(50),
    Soyad NVARCHAR(50),
    TCKimlikNo CHAR(11),
    Telefon NVARCHAR(50),
    Mail NVARCHAR(100),
    Cinsiyet NVARCHAR(10),
    DogumTarihi DATE -- Doğum tarihi
);

CREATE TABLE Tedarikciler (
    TedarikciID INT IDENTITY(1,1) PRIMARY KEY,
    FirmaAdi NVARCHAR(100),
    YetkiliKisi NVARCHAR(100),
    Telefon NVARCHAR(50),
    Mail NVARCHAR(100),
    VergiNo NVARCHAR(20),
    IBAN NVARCHAR(34),

);


CREATE TABLE Personeller (
    PersonelID INT IDENTITY(1,1) PRIMARY KEY,
    Ad NVARCHAR(50),
    Soyad NVARCHAR(50),
    TCKimlikNo CHAR(11),
    Telefon NVARCHAR(50),
    Cinsiyet NVARCHAR(10),
    PersonelNo NVARCHAR(20),
    Pozisyon NVARCHAR(50), -- 'Garson', 'Asci', 'Barista'
    Maas DECIMAL(10,2),
    DogumTarihi DATE NULL, -- Doğum tarihi (isteğe bağlı)
    BaslamaTarihi DATE,
	AyrilmaTarihi DATE NULL -- Personel ayrılmi (eğer varsa)
);


CREATE TABLE SiparisSekilleri (
    SiparisSekilID INT IDENTITY(1,1) PRIMARY KEY,
    SiparisSekli NVARCHAR(20) -- 'Masa', 'Tezgahtan'

);

CREATE TABLE SiparisDurumlari (
    SiparisDurumID INT IDENTITY(1,1) PRIMARY KEY,
    SiparisDurumu NVARCHAR(20) -- 'Tamamlandi', 'Iptal''

);

CREATE TABLE Siparisler (
    SiparisID INT IDENTITY(1,1) PRIMARY KEY,
    MusteriID INT FOREIGN KEY REFERENCES Musteriler(MusteriID),
	PersonelID INT FOREIGN KEY REFERENCES Personeller(PersonelID), -- Siparişi alan garson veya Tezgahtar'ın ID'si
    SiparisSekliID INT FOREIGN KEY REFERENCES SiparisSekilleri(SiparisSekilID),
    SiparisDurumID INT FOREIGN KEY REFERENCES SiparisDurumlari(SiparisDurumID),
    MasaID INT NULL FOREIGN KEY REFERENCES Masalar(MasaID),
    SiparisNo NVARCHAR(50),
    OdemeTuru NVARCHAR(20), -- 'Nakit', 'Kredi Kartı', 'Hediye Çeki'
	SiparisNotu NVARCHAR(200) NULL, -- Sipariş notu (isteğe bağlı, örn: 'Acı olsun', 'Tatlı olsun' gibi)
    Tarih DATE, -- Sipariş tarihi
    IndirimOrani DECIMAL(5,2) NULL, -- İndirim oranı (isteğe bağlı)
);


CREATE TABLE SiparisDetay (
    SiparisDetayID INT IDENTITY(1,1) PRIMARY KEY,
    SiparisID INT FOREIGN KEY REFERENCES Siparisler(SiparisID),
    UrunID INT FOREIGN KEY REFERENCES Urunler(UrunID),
    Adet INT,
    BirimFiyat DECIMAL(10,2), -- Ürünün birim fiyatı
);


CREATE TABLE Hammaddeler (
    HammaddeID INT IDENTITY(1,1) PRIMARY KEY,
    HammaddeAdi NVARCHAR(100),
    Birim NVARCHAR(20),         -- kg, lt, adet
    MinStokMiktari DECIMAL(10,2) NULL
);

CREATE TABLE SarfMalzemeler (
    SarfMalzemeID INT IDENTITY(1,1) PRIMARY KEY,
    SarfMalzemeAdi NVARCHAR(100),
    Birim NVARCHAR(20),         -- kg, lt, adet
    MinStokMiktari DECIMAL(10,2) NULL
);


CREATE TABLE HammaddeAlislari (
    HammaddeAlisID INT IDENTITY(1,1) PRIMARY KEY,
    TedarikciID INT FOREIGN KEY REFERENCES Tedarikciler(TedarikciID),
    HammaddeID INT FOREIGN KEY REFERENCES Hammaddeler(HammaddeID),
    Miktar DECIMAL(10,2),
    BirimFiyat DECIMAL(10,2),
    ToplamAlisFiyati DECIMAL(10,2),
    Tarih DATE
);

CREATE TABLE SarfMalzemeAlislari (
    SarfMalzemeAlisID INT IDENTITY(1,1) PRIMARY KEY,
    TedarikciID INT FOREIGN KEY REFERENCES Tedarikciler(TedarikciID),
    SarfMalzemeID INT FOREIGN KEY REFERENCES SarfMalzemeler(SarfMalzemeID),
    Miktar DECIMAL(10,2),
    BirimFiyat DECIMAL(10,2),
    ToplamAlisFiyati DECIMAL(10,2),
    Tarih DATE
);


CREATE TABLE MaliyetKalemleri (
    MaliyetKalemiID INT IDENTITY(1,1) PRIMARY KEY,
    MaliyetKalemiAdi NVARCHAR(100),
);

CREATE TABLE Maliyetler (
    MaliyetID INT IDENTITY(1,1) PRIMARY KEY,
    MaliyetKalemiID INT FOREIGN KEY REFERENCES MaliyetKalemleri(MaliyetKalemiID),
    Tutar DECIMAL(10,2),
    Aciklama NVARCHAR(200),
    Tarih DATE -- Maliyet tarihi
);



CREATE TABLE PersonelMaasOdemeleri (
    PersonelMaasOdemeleriID INT IDENTITY(1,1) PRIMARY KEY,
    PersonelID INT FOREIGN KEY REFERENCES Personeller(PersonelID),
    OdenenTutar DECIMAL(10,2),
    OdemeTarihi DATE
);



